import {createPaintedGrass} from './painted-grass.js';
const $=id=>document.getElementById(id),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x303b33);renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;$('scene').append(renderer.domElement);
const scene=new T.Scene(),camera=new T.OrthographicCamera(),loader=new T.TextureLoader(),sun=new T.DirectionalLight(0xffecd5,2.4);sun.position.set(-4,8,5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-4,right:4,top:4,bottom:-4});sun.shadow.normalBias=.012;scene.add(sun,new T.HemisphereLight(0xfff1d3,0x778878,2));
const floor=new T.Mesh(new T.PlaneGeometry(30,30),createPaintedGrass());floor.rotation.x=-Math.PI/2;floor.position.y=-.01;floor.receiveShadow=true;scene.add(floor);
const wall=new T.Group(),wallMat=new T.MeshStandardMaterial({color:0x9b9683,roughness:1}),frameMat=new T.MeshStandardMaterial({color:0x514f3c,roughness:.9});scene.add(wall);
function box(y,z,h,w,material=wallMat,depth=.16){const m=new T.Mesh(new T.BoxGeometry(depth,h,w),material);m.position.set(0,y,z);m.castShadow=m.receiveShadow=true;wall.add(m);}
box(.425,0,.85,1);box(1.775,0,.45,1);for(const z of [-.8,.8])box(1,z,2,.6);
for(const y of [.8625,1.5375])box(y,0,.025,1,frameMat,.18);for(const z of [-.4875,.4875])box(1.2,z,.7,.025,frameMat,.18);
const glass=createWindowShatter({kind:'window-concrete'});glass.group.rotation.y=Math.PI/2;scene.add(glass.group);
const audio=new Audio('../assets/audio/glass-smash-rubberduck-cc0.ogg');audio.volume=.65;audio.preload='auto';let audioStarts=0,audioError=null;let motion,worker,paint,playing=false,time=0,last=performance.now(),result;
function stopAudio(){audio.pause();audio.currentTime=0;}
function render(){if(!motion)return;result=motion.apply(time);glass.sample(result.glassTime);wall.visible=!$('cutaway').checked;renderer.render(scene,camera);$('time').value=time;$('status').textContent=`${time.toFixed(2)} / ${motion.duration.toFixed(2)} s · ${result.phase}`;$('play').textContent=playing?'Pause':'Play';}
function resize(){const w=$('scene').clientWidth,h=$('scene').clientHeight;renderer.setSize(w,h,false);const span=$('scale').value==='gameplay'?h/85:3.5;camera.left=-span*w/h/2;camera.right=span*w/h/2;camera.top=span/2;camera.bottom=-span/2;camera.near=.01;camera.far=100;camera.position.set(...({three:[-4,2.7,5],side:[.2,1.8,6],rear:[-6,2,0],front:[6,2,0]}[$('view').value]));camera.lookAt(.15,1,0);camera.updateProjectionMatrix();render();}
