$('play').onclick=()=>{if(!motion)return;if(time>=motion.duration)time=0;playing=!playing;last=performance.now();if(!playing)stopAudio();render();};$('reset').onclick=()=>motion&&seek(0);$('time').oninput=()=>motion&&seek(Number($('time').value));for(const id of ['view','scale'])$(id).onchange=resize;$('cutaway').onchange=render;$('sound').onchange=()=>{if(!$('sound').checked)stopAudio();};window.addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{if(document.hidden){playing=false;stopAudio();render();}});
window.windowVaultStudy={ready:false,seek,diagnostics:()=>({ready:!!motion,time,duration:motion?.duration,...result,glass:glass.diagnostics(),audio:{ready:audio.readyState,starts:audioStarts,error:audioError}}),get worker(){return worker;}};
async function load(){const p=ANIMAL_MOTION_CATALOG[0],response=await fetch(p.file);if(!response.ok)throw Error('Horse mesh failed to load');const texture=await loader.loadAsync(LIGHT_ATLAS);worker=p.create(await response.json(),texture);paint=await createAnimalPaint(renderer,worker,p,loader);for(const part of worker.parts){part.material=paint.material;part.castShadow=part.receiveShadow=true;}scene.add(worker.root);motion=createWindowVault(worker);$('time').max=motion.duration;for(const phase of motion.phases){const b=document.createElement('button');b.textContent=phase.label;b.onclick=()=>seek((phase.start+phase.end)/2);$('phases').append(b);}$('play').disabled=false;window.windowVaultStudy.ready=true;resize();}
const params=new URLSearchParams(location.search);for(const id of ['view','scale','speed'])if([...$(id).options].some(o=>o.value===params.get(id)))$(id).value=params.get(id);
function tick(now){if(playing&&motion){const previous=time;time=Math.min(motion.duration,time+Math.min((now-last)/1000,.05)*Number($('speed').value));if(previous<WINDOW_VAULT_IMPACT&&time>=WINDOW_VAULT_IMPACT&&$('sound').checked){stopAudio();audio.playbackRate=Number($('speed').value);audio.play().then(()=>{audioStarts++;audioError=null;}).catch(e=>{audioError=e.message;});}if(time>=motion.duration)playing=false;render();}last=now;requestAnimationFrame(tick);}resize();load().catch(e=>{$('status').textContent=e.message;console.error(e);});requestAnimationFrame(tick);
